# ---------------------------------------------------------------------------
# Translator API
# ---------------------------------------------------------------------------


def normalize_locale(locale: Any) -> str:
    """Return a supported locale code (defaulting to ``DEFAULT_LOCALE``)."""
    if not isinstance(locale, str):
        return DEFAULT_LOCALE
    code = locale.strip().lower()[:2]
    return code if code in SUPPORTED_LOCALES else DEFAULT_LOCALE


def t(tool_id: str, key: str, locale: str | None = None, **vars: Any) -> str:
    """Resolve a translation template.

    Lookup order:
      1. ``_TOOLS[tool_id][locale][key]``
      2. ``_TOOLS[tool_id][DEFAULT_LOCALE][key]``
      3. ``_COMMON[locale][key]``
      4. ``_COMMON[DEFAULT_LOCALE][key]``
      5. ``key`` itself

    The result is then ``str.format(**vars)``-ed (missing placeholders
    raise ``KeyError`` like Python normally does, so every call site
    must pass the variables the template expects).
    """
    target_locale = normalize_locale(locale)

    template: str | None = None
    tool_block = _TOOLS.get(tool_id)
    if tool_block:
        template = tool_block.get(target_locale, {}).get(key)
        if template is None and target_locale != DEFAULT_LOCALE:
            template = tool_block.get(DEFAULT_LOCALE, {}).get(key)
    if template is None:
        template = _COMMON.get(target_locale, {}).get(key)
        if template is None and target_locale != DEFAULT_LOCALE:
            template = _COMMON.get(DEFAULT_LOCALE, {}).get(key)
    if template is None:
        template = key

    if not vars:
        return template
    try:
        return template.format(**vars)
    except (KeyError, IndexError, ValueError):
        # Don't blow up on missing placeholders in user-facing flows;
        # the missing variable name is more useful as a leaked
        # ``{var}`` than a 500 error.
        return template


def has_translation(tool_id: str, key: str, locale: str | None = None) -> bool:
    """Return True when a non-fallback translation exists."""
    target_locale = normalize_locale(locale)
    tool_block = _TOOLS.get(tool_id, {})
    if key in tool_block.get(target_locale, {}):
        return True
    return key in _COMMON.get(target_locale, {})


def signoff_html(locale: str | None, station: str = "", *, ops_team: bool = True) -> str:
    """Return a translated ``<p>Saludos,<br>{station} Ops Team</p>`` block."""
    regards = t("common", "signoff.regards", locale)
    if ops_team:
        team = t(
            "common",
            "signoff.ops_team_full" if station else "signoff.ops_team",
            locale,
            station=station,
        )
    else:
        team = station or t("common", "signoff.ops_team", locale)
    return f"<p>{regards},<br>{team}</p>"


def footer_message(locale: str | None) -> str:
    """Return the translated email footer line."""
    return t("common", "footer.message", locale)


# ---------------------------------------------------------------------------
# Bulk registration helper (so tools can register their own blocks at import
# time without modifying this module).
# ---------------------------------------------------------------------------


def register_tool_messages(tool_id: str, blocks: dict[str, dict[str, str]]) -> None:
    """Register a tool's translation block.

    ``blocks`` is ``{locale -> {key -> template}}`` and **must** contain
    at least the ``DEFAULT_LOCALE`` key. Existing entries are replaced
    (last-wins) so a tool can opt to override common reminders.
    """
    if DEFAULT_LOCALE not in blocks:
        raise ValueError(
            f"Tool {tool_id!r} translations must include {DEFAULT_LOCALE!r}"
        )
    existing = _TOOLS.setdefault(tool_id, {})
    for locale, mapping in blocks.items():
        target = existing.setdefault(locale, {})
        target.update(mapping)


__all__ = [
    "DEFAULT_LOCALE",
    "SUPPORTED_LOCALES",
    "normalize_locale",
    "t",
    "has_translation",
    "signoff_html",
    "footer_message",
    "register_tool_messages",
    "translate_message",
    "translate_status",
]


