def translate_status(value: str, locale: str | None) -> str:
    """Translate a package status/state to the target UI locale.

    Statuses arrive in English from PerfectMile / SCC (e.g. ``"Delivery
    Rejected"`` or ``"PICKED_UP"``). We normalize them and look up a
    per-locale label so the operator sees the status in the selected
    language (Spanish by default). Unknown statuses are returned with a
    light Title Case cleanup so they remain readable.
    """
    import re as _re

    if not value or not isinstance(value, str):
        return ""
    target = normalize_locale(locale)
    norm = _re.sub(r"[^a-z0-9]+", " ", value.strip().lower()).strip()
    norm = _re.sub(r"\s+", " ", norm)
    entry = _STATUS_MAP.get(norm)
    if entry:
        return entry.get(target) or entry.get(DEFAULT_LOCALE) or value
    # Unknown status: clean up underscores/casing for readability.
    return value.replace("_", " ").strip().title()


def translate_message(text: str, locale: str | None) -> str:
    """Best-effort translation of legacy hardcoded prose.

    Apply this on a fully-rendered Slack/email body to swap common
    Spanish phrases (greetings, signoffs, section titles) with their
    locale equivalent. Tools that adopt the proper ``t()`` API don't
    need this — but it lets us roll i18n out incrementally without
    breaking tools that still hardcode Spanish.
    """
    if not text or not isinstance(text, str):
        return text
    target = normalize_locale(locale)
    if target == DEFAULT_LOCALE:
        return text
    out = text
    # Process keys longest-first so substring overlaps don't clobber
    # each other ("Buenas tardes HUB team" before "Buenas tardes").
    for source in sorted(_LEGACY_PHRASE_MAP.keys(), key=len, reverse=True):
        replacements = _LEGACY_PHRASE_MAP[source]
        translation = replacements.get(target)
        if translation and source in out:
            out = out.replace(source, translation)
    return out


