def _merge_italian() -> None:
    """Wire the Italian strings into the shared registries at import time."""
    _COMMON["it"] = dict(_COMMON_IT)
    _LEGACY_PHRASE_MAP.update(_LEGACY_PHRASE_EXTRA)
    for tool_id, block in _TOOLS_IT.items():
        _TOOLS.setdefault(tool_id, {})["it"] = dict(block)
    for source, it_value in _LEGACY_PHRASE_IT.items():
        if source in _LEGACY_PHRASE_MAP:
            _LEGACY_PHRASE_MAP[source]["it"] = it_value
    for source, en_value in _LEGACY_PHRASE_EN_FILL.items():
        if source in _LEGACY_PHRASE_MAP:
            _LEGACY_PHRASE_MAP[source].setdefault("en", en_value)
    for norm, it_value in _STATUS_IT.items():
        if norm in _STATUS_MAP:
            _STATUS_MAP[norm]["it"] = it_value


_merge_italian()


